INSERT OR REPLACE INTO posts (id,slug,title,excerpt,body,category,image_url,video_url,tags,published,noindex,featured,published_at,created_at,updated_at,search_text) VALUES ('32f27e63-0f3b-493b-a150-131250e19cff','resulta-que-la-gente-de-nueva-santa','Resulta que la gente de Nueva Santa','Resulta que la gente de Nueva Santa Rosa está de fiesta porque por fin inauguraron su pozo mecánico y toda la tubería para que el agua llegue a las casas. El mejor alcalde, Enrique Arredondo, se puso las pilas junto…','Resulta que la gente de Nueva Santa Rosa está de fiesta porque por fin inauguraron su pozo mecánico y toda la tubería para que el agua llegue a las casas. El mejor alcalde, Enrique Arredondo, se puso las pilas junto con su equipo, porque sabían que la patojada estaba sufriendo por la falta de agua.

