INSERT OR REPLACE INTO posts (id,slug,title,excerpt,body,category,image_url,video_url,tags,published,noindex,featured,published_at,created_at,updated_at,search_text) VALUES ('3cdc67fc-8d3b-4dac-9768-325009d22025','barberena-cruce-de-senalamientos-entre-lico-cruz-y-pepe-rueda','barberena Cruce de señalamientos entre Lico Cruz y Pepe Rueda','BARBERENA  Cruce de señalamientos entre Lico Cruz y Pepe Rueda','BARBERENA  Cruce de señalamientos entre Lico Cruz y Pepe Rueda

