INSERT OR REPLACE INTO posts (id,slug,title,excerpt,body,category,image_url,video_url,tags,published,noindex,featured,published_at,created_at,updated_at,search_text) VALUES ('9176ac78-adff-4b60-bade-9e919caa76cc','tome-nota-de-la-calle-vieja-que-va','Tome nota de la calle vieja que va','Tome nota, de la calle vieja que va de Villa Graciela hacia Barberena tienen un bloqueo sus habitantes en donde están cobrando una extorsión, ya que te cobran Q10.00 si vas en moto y Q20.00 si vas en carro, según,…','Tome nota, de la calle vieja que va de Villa Graciela hacia Barberena tienen un bloqueo sus habitantes en donde están cobrando una extorsión, ya que te cobran Q10.00 si vas en moto y Q20.00 si vas en carro, según, para arreglar las calles, cosa que no les compete a ellos pues es la municipalidad la que se tendría que encargar de dichos trabajos. Si no pagas la extorsión te ponen al frente y tratan de botarte o golpearte, amenazan con prenderte fuego. En la foto se puede observar a una integrante del COCODE recibiendo dinero.','barberena','https://img.barberenamimunicipio.top/122167039778318393.jpg',NULL,'["Barberena", "Villa Graciela", "Obras públicas", "Municipalidad"]',1,0,0,'2025-03-31T18:39:20.000Z','2026-09-27T03:32:48.574Z','2026-10-31T00:28:52.938Z','tome nota de la calle vieja que va tome nota, de la calle vieja que va de villa graciela hacia barberena tienen un bloqueo sus habitantes en donde estan cobrando una extorsion, ya que te cobran q10.00 si vas en moto y q20.00 si vas en carro, segun,… barberena villa graciela obras publicas municipalidad tome nota, de la calle vieja que va de villa graciela hacia barberena tienen un bloqueo sus habitantes en donde estan cobrando una extorsion, ya que te cobran q10.00 si vas en moto y q20.00 si vas en carro, segun, para arreglar las calles, cosa que no les compete a ellos pues es la municipalidad la que se tendria que encargar de dichos trabajos. si no pagas la extorsion te ponen al frente y tratan de botarte o golpearte, amenazan con prenderte fuego. en la foto se puede observar a una integrante del cocode recibiendo dinero.');
INSERT OR REPLACE INTO posts (id,slug,title,excerpt,body,category,image_url,video_url,tags,published,noindex,featured,published_at,created_at,updated_at,search_text) VALUES ('91a33c20-5ae3-40a1-a799-5bc84deee7d5','manana-vendra-la-futura-presidenta-de-guatemala','Mañana vendrá la futura presidenta de Guatemala','MAÑANA VENDRÁ LA FUTURA PRESIDENTA DE GUATEMALA','MAÑANA VENDRÁ LA FUTURA PRESIDENTA DE GUATEMALA

Mañana se espera la visita de Sandra Torres. ¿El motivo? Reunirse con el mejor alcalde para la afiliación y capacitación que organiza el partido UNE.

Todos en el país aman a la ex primera dama — hay quienes piden que la nombren presidenta desde ya. Los tishudos no son la excepción: están entusiasmados y no querrían perderse la visita.

